import{_ as a,a0 as i,w as p,s as T,ao as s,I as d,x as o,a1 as n,A as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"漫遊 HTTP/2 | LCTT x X-CMD","titleTemplate":false,"description":"漫遊 HTTP/2 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"漫遊 HTTP/2 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"漫遊 HTTP/2 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160813 Journey-to-HTTP2","title":"漫遊 HTTP/2","tag":"201609","desc":""},"relativePath":"201609/20160813 Journey-to-HTTP2.md","filePath":"[post].md"}'),r={name:"201609/20160813 Journey-to-HTTP2.md"};function c(P,e,h,H,u,g){const t=i("Link");return p(),T("div",null,[e[45]||(e[45]=s(`<h1 id="漫遊-http-2" tabindex="-1">漫遊 HTTP/2 <a class="header-anchor" href="#漫遊-http-2" aria-label="Permalink to “漫遊 HTTP/2”">​</a></h1><p>自從我寫了上一篇博文之後，就再也找不到空閒時間寫文章了。今天我終於可以抽出時間寫一些關於 HTTP 的東西。</p><p>我認為每一個 web 開發者都應該對這個支撐了整個 Web 世界的 HTTP 協議有所瞭解，這樣才能幫助你更好的完成開發任務。</p><p>在這篇文章中，我將討論什麼是 HTTP，它是怎麼產生的，它的地位，以及我們應該怎麼使用它。</p><h3 id="http-是什麼" tabindex="-1">HTTP 是什麼 <a class="header-anchor" href="#http-是什麼" aria-label="Permalink to “HTTP 是什麼”">​</a></h3><p>首先我們要明白 HTTP 是什麼。HTTP 是一個基於 <code>TCP/IP</code> 的應用層通信協議，它是客户端和服務端在互聯網互相通訊的標準。它定義了內容是如何通過互聯網進行請求和傳輸的。HTTP 是在應用層中抽象出的一個標準，使得主機（客户端和服務端）之間的通信得以通過 <code>TCP/IP</code> 來進行請求和響應。TCP 默認使用的端口是 <code>80</code>，當然也可以使用其它端口，比如 HTTPS 使用的就是 <code>443</code> 端口。</p><h3 id="http-0-9-單行協議-1991" tabindex="-1"><code>HTTP/0.9</code> - 單行協議 (1991) <a class="header-anchor" href="#http-0-9-單行協議-1991" aria-label="Permalink to “HTTP/0.9 - 單行協議 (1991)”">​</a></h3><p>HTTP 最早的規範可以追溯到 1991 年，那時候的版本是 <code>HTTP/0.9</code>，該版本極其簡單，只有一個叫做 <code>GET</code> 的 請求方式。如果客户端要訪問服務端上的一個頁面，只需要如下非常簡單的請求：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET /index.html</span></span></code></pre></div><p>服務端的響應類似如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(response body)</span></span>
<span class="line"><span>(connection closed)</span></span></code></pre></div><p>就這麼簡單，服務端捕獲到請求後立馬返回 HTML 並且關閉連接，在這之中：</p><ul><li>沒有頭信息（headers）</li><li>僅支持 <code>GET</code> 這一種請求方法</li><li>必須返回 HTML</li></ul><p>如同你所看到的，當時的 HTTP 協議只是一塊基礎的墊腳石。</p><h3 id="http-1-0-1996" tabindex="-1">HTTP/1.0 - 1996 <a class="header-anchor" href="#http-1-0-1996" aria-label="Permalink to “HTTP/1.0 - 1996”">​</a></h3><p>在 1996 年，新版本的 HTTP 對比之前的版本有了極大的改進，同時也被命名為 <code>HTTP/1.0</code>。</p><p>與 <code>HTTP/0.9</code> 只能返回 HTML 不同的是，<code>HTTP/1.0</code> 支持處理多種返回的格式，比如圖片、視頻、文本或者其他格式的文件。它還增加了更多的請求方法（如 <code>POST</code> 和 <code>HEAD</code>），請求和響應的格式也相應做了改變，兩者都增加了頭信息；引入了狀態碼來定義返回的特徵；引入了字符集支持；支持多段類型（multi-part）、用户驗證信息、緩存、內容編碼格式等等。</p><p>一個簡單的 HTTP/1.0 請求大概是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>GET / HTTP/1.0</span></span>
<span class="line"><span>Host: kamranahmed.info</span></span>
<span class="line"><span>User-Agent: Mozilla/5.0 (Macintosh; Intel Mac OS X 10_10_5)</span></span>
<span class="line"><span>Accept: */*</span></span></code></pre></div><p>正如你所看到的，在請求中附帶了客户端中的一些個人信息、響應類型要求等內容。這些是在 <code>HTTP/0.9</code> 無法實現的，因為那時候沒有頭信息。</p><p>一個對上述請求的響應例子如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HTTP/1.0 200 OK</span></span>
<span class="line"><span>Content-Type: text/plain</span></span>
<span class="line"><span>Content-Length: 137582</span></span>
<span class="line"><span>Expires: Thu, 05 Dec 1997 16:00:00 GMT</span></span>
<span class="line"><span>Last-Modified: Wed, 5 August 1996 15:55:28 GMT</span></span>
<span class="line"><span>Server: Apache 0.84</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(response body)</span></span>
<span class="line"><span>(connection closed)</span></span></code></pre></div><p>從 <code>HTTP/1.0</code> （HTTP 後面跟的是版本號）早期開始，在狀態碼 <code>200</code> 之後就附帶一個原因短語（你可以用來描述狀態碼）。</p><p>在這個較新一點的版本中，請求和響應的頭信息仍然必須是 <code>ASCII</code> 編碼，但是響應的內容可以是任意類型，如圖片、視頻、HTML、文本或其他類型，服務器可以返回任意內容給客户端。所以這之後，<code>HTTP</code> 中的“超文本（Hyper Text）”成了名不副實。 <code>HMTP</code> （超媒體傳輸協議 - Hypermedia transfer protocol）可能會更有意義，但是我猜我們還是會一直沿用這個名字。</p><p><code>HTTP/1.0</code> 的一個主要缺點就是它不能在一個連接內擁有多個請求。這意味着，當客户端需要從服務器獲取東西時，必須建立一個新的 TCP 連接，並且處理完單個請求後連接即被關閉。需要下一個東西時，你必須重新建立一個新的連接。這樣的壞處在哪呢？假設你要訪問一個有 <code>10</code> 張圖片，<code>5</code> 個樣式表（stylesheet）和 <code>5</code> 個 JavaScript 的總計 <code>20</code> 個文件才能完整展示的一個頁面。由於一個連接在處理完成一次請求後即被關閉，所以將有 <code>20</code> 個單獨的連接，每一個文件都將通過各自對應的連接單獨處理。當連接數量變得龐大的時候就會面臨嚴重的性能問題，因為 <code>TCP</code> 啓動需要經過三次握手，才能緩慢開始。</p><h4 id="三次握手" tabindex="-1">三次握手 <a class="header-anchor" href="#三次握手" aria-label="Permalink to “三次握手”">​</a></h4><p>三次握手是一個簡單的模型，所有的 <code>TCP</code> 連接在傳輸應用數據之前都需要在三次握手中傳輸一系列數據包。</p><ul><li><code>SYN</code> - 客户端選取一個隨機數，我們稱為 <code>x</code>，然後發送給服務器。</li><li><code>SYN ACK</code> - 服務器響應對應請求的 <code>ACK</code> 包中，包含了一個由服務器隨機產生的數字，我們稱為 <code>y</code>，並且把客户端發送的 <code>x+1</code>，一併返回給客户端。</li><li><code>ACK</code> - 客户端在從服務器接受到 <code>y</code> 之後把 <code>y</code> 加上 <code>1</code> 作為一個 <code>ACK</code> 包返回給服務器。</li></ul><p>一旦三次握手完成後，客户端和服務器之間就可以開始交換數據。值得注意的是，當客户端發出最後一個 <code>ACK</code> 數據包後，就可以立刻向服務器發送應用數據包，而服務器則需要等到收到這個 <code>ACK</code> 數據包後才能接受應用數據包。</p><p><img src="http://i.imgur.com/uERG2G2.png" alt=""></p><blockquote><p>請注意，上圖有點小問題，客户端發回的最後一個 ACK 包僅包含 <code>y+1</code>，上圖應該是 <code>ACK:y+1</code> 而不是 <code>ACK:x+1,y+1</code></p></blockquote><p>然而，某些 HTTP/1.0 的實現試圖通過新引入一個稱為 <code>Connection: keep-alive</code> 的頭信息來克服這一問題，這個頭信息意味着告訴服務器“嘿，服務器，請不要關閉此連接，我還要用它”。但是，這並沒有得到廣泛的支持，問題依然存在。</p><p>除了無連接之外，HTTP 還是一個無狀態的協議，即服務器不維護有關客户端的信息。因此每個請求必須給服務器必要的信息才能完成請求，每個請求都與之前的舊的請求無關。所以，這增加了推波助瀾的作用，客户端除了需要新建大量連接之外，在每次連接中還需要發送許多重複的數據，這導致了帶寬的大量浪費。</p><h3 id="http-1-1-1999" tabindex="-1"><code>HTTP/1.1</code> - 1999 <a class="header-anchor" href="#http-1-1-1999" aria-label="Permalink to “HTTP/1.1 - 1999”">​</a></h3><p><code>HTTP/1.0</code> 經過僅僅 3 年，下一個版本，即 <code>HTTP/1.1</code> 就在 1999 年發佈了，改進了它的前身很多問題，主要的改進包括：</p><ul><li><strong>增加了許多 HTTP 請求方法</strong>，包括 <code>PUT</code>、<code>PATCH</code>、<code>HEAD</code>、<code>OPTIONS</code>、<code>DELETE</code>。</li><li><strong>主機標識符</strong> <code>Host</code> 在 <code>HTTP/1.0</code> 並不是必須的，而在 <code>HTTP/1.1</code> 是必須的。</li><li>如上所述的<strong>持久連接</strong>。在 <code>HTTP/1.0</code> 中每個連接只有一個請求並在該請求結束後被立即關閉，這導致了性能問題和增加了延遲。 <code>HTTP/1.1</code> 引入了持久連接，即連接在默認情況下是不關閉並保持開放的，這允許多個連續的請求使用這個連接。要關閉該連接只需要在頭信息加入 <code>Connection: close</code>，客户通常在最後一個請求裏發送這個頭信息就能安全地關閉連接。</li><li>新版本還引入了“<strong>管線化（pipelining）</strong>”的支持，客户端可以不用等待服務器返回響應，就能在同一個連接內發送多個請求給服務器，而服務器必須以接收到的請求相同的序列發送響應。但是你可能會問了，客户端如何知道哪裏是第一個響應下載完成而下一個響應內容開始的地方呢？要解決這個問題，頭信息必須有 <code>Content-Length</code>，客户可以使用它來確定哪些響應結束之後可以開始等待下一個響應。 <ul><li>值得注意的是，為了從持久連接或管線化中受益， 頭部信息必須包含 <code>Content-Length</code>，因為這會使客户端知道什麼時候完成了傳輸，然後它可以發送下一個請求（持久連接中，以正常的依次順序發送請求）或開始等待下一個響應（啓用管線化時）。</li><li>但是，使用這種方法仍然有一個問題。那就是，如果數據是動態的，服務器無法提前知道內容長度呢？那麼在這種情況下，你就不能使用這種方法中獲益了嗎？為了解決這個問題，<code>HTTP/1.1</code> 引進了分塊編碼。在這種情況下，服務器可能會忽略 <code>Content-Length</code> 來支持分塊編碼（更常見一些）。但是，如果它們都不可用，那麼連接必須在請求結束時關閉。</li></ul></li><li>在動態內容的情況下<strong>分塊傳輸</strong>，當服務器在傳輸開始但無法得到 <code>Content-Length</code> 時，它可能會開始按塊發送內容（一塊接一塊），並在傳輸時為每一個小塊添加 <code>Content-Length</code>。當發送完所有的數據塊後，即整個傳輸已經完成後，它發送一個空的小塊，比如設置 <code>Content-Length</code> 為 0 ，以便客户端知道傳輸已完成。為了通知客户端塊傳輸的信息，服務器在頭信息中包含了 <code>Transfer-Encoding: chunked</code>。</li><li>不像 HTTP/1.0 中只有 Basic 身份驗證方式，<code>HTTP/1.1</code> 包括摘要驗證方式（digest authentication）和代理驗證方式（proxy authentication）。</li><li>緩存。</li><li>範圍請求（Byte Ranges）。</li><li>字符集。</li><li>內容協商（Content Negotiation）。</li><li>客户端 cookies。</li><li>支持壓縮。</li><li>新的狀態碼。</li><li>等等。</li></ul>`,36)),d("p",null,[e[2]||(e[2]=o("我不打算在這裏討論所有 ",-1)),e[3]||(e[3]=d("code",null,"HTTP/1.1",-1)),e[4]||(e[4]=o(" 的特性，因為你可以圍繞這個話題找到很多關於這些的討論。我建議你閲讀 ",-1)),n(t,{href:"http://www.ra.ethz.ch/cdstore/www8/data/2136/pdf/pd1.pdf"},{default:l(()=>[...e[0]||(e[0]=[d("code",null,"HTTP/1.0",-1),o(" 和 ",-1),d("code",null,"HTTP/1.1",-1),o(" 版本之間的主要差異",-1)])]),_:1}),e[5]||(e[5]=o("，希望瞭解更多可以讀",-1)),n(t,{href:"https://tools.ietf.org/html/rfc2616"},{default:l(()=>[...e[1]||(e[1]=[o("原始的 RFC",-1)])]),_:1}),e[6]||(e[6]=o("。",-1))]),d("p",null,[e[8]||(e[8]=d("code",null,"HTTP/1.1",-1)),e[9]||(e[9]=o(" 在 1999 年推出，到現在已經是多年前的標準。雖然，它比前一代改善了很多，但是網絡日新月異，它已經垂垂老矣。相比之前，加載網頁更是一個資源密集型任務，打開一個簡單的網頁已經需要建立超過 30 個連接。你或許會説，",-1)),e[10]||(e[10]=d("code",null,"HTTP/1.1",-1)),e[11]||(e[11]=o(" 具有持久連接，為什麼還有這麼多連接呢？其原因是，在任何時刻 ",-1)),e[12]||(e[12]=d("code",null,"HTTP/1.1",-1)),e[13]||(e[13]=o(" 只能有一個未完成的連接。 ",-1)),e[14]||(e[14]=d("code",null,"HTTP/1.1",-1)),e[15]||(e[15]=o(" 試圖通過引入管線來解決這個問題，但它並沒有完全地解決。因為一旦管線遇到了緩慢的請求或龐大的請求，後面的請求便被阻塞住，它們必須等待上一個請求完成。為了克服 ",-1)),e[16]||(e[16]=d("code",null,"HTTP/1.1",-1)),e[17]||(e[17]=o(" 的這些缺點，開發人員開始實現一些解決方法，例如使用 spritesheets、在 CSS 中編碼圖像、單個巨型 CSS / JavaScript 文件、",-1)),n(t,{href:"https://www.maxcdn.com/one/visual-glossary/domain-sharding-2/"},{default:l(()=>[...e[7]||(e[7]=[o("域名切分",-1)])]),_:1}),e[18]||(e[18]=o("等。",-1))]),e[46]||(e[46]=s('<h3 id="spdy-2009" tabindex="-1">SPDY - 2009 <a class="header-anchor" href="#spdy-2009" aria-label="Permalink to “SPDY - 2009”">​</a></h3><p>谷歌走在業界前列，為了使網絡速度更快，提高網絡安全，同時減少網頁的等待時間，他們開始實驗替代的協議。在 2009 年，他們宣佈了 <code>SPDY</code>。</p><blockquote><p><code>SPDY</code> 是谷歌的商標，而不是一個縮寫。</p></blockquote><p>顯而易見的是，如果我們繼續增加帶寬，網絡性能開始的時候能夠得到提升，但是到了某個階段後帶來的性能提升就很有限了。但是如果把這些優化放在等待時間上，比如減少等待時間，將會有持續的性能提升。這就是 <code>SPDY</code> 優化之前的協議的核心思想，減少等待時間來提升網絡性能。</p><blockquote><p>對於那些不知道其中區別的人，等待時間就是延遲，即數據從源到達目的地需要多長時間（單位為毫秒），而帶寬是每秒鐘數據的傳輸量（比特每秒）。</p></blockquote><p><code>SPDY</code> 的特點包括：複用、壓縮、優先級、安全性等。我不打算展開 <code>SPDY</code> 的細節。在下一章節，當我們將介紹 <code>HTTP/2</code>，這些都會被提到，因為 <code>HTTP/2</code> 大多特性是從 <code>SPDY</code> 受啓發的。</p><p><code>SPDY</code> 沒有試圖取代 HTTP，它是處於應用層的 HTTP 之上的一個傳輸層，它只是在請求被髮送之前做了一些修改。它開始成為事實標準，大多數瀏覽器都開始支持了。</p><p>2015年，谷歌不想有兩個相互競爭的標準，所以他們決定將其合併到 HTTP 協議，這樣就導致了 <code>HTTP/2</code> 的出現和 <code>SPDY</code> 的廢棄。</p><h3 id="http-2-2015" tabindex="-1"><code>HTTP/2</code> - 2015 <a class="header-anchor" href="#http-2-2015" aria-label="Permalink to “HTTP/2 - 2015”">​</a></h3><p>現在想必你明白了為什麼我們需要另一個版本的 HTTP 協議了。 <code>HTTP/2</code> 是專為了低延遲地內容傳輸而設計。主要特點和與 <code>HTTP/1.1</code> 的差異包括：</p><ul><li>使用二進制替代明文</li><li>多路傳輸 - 多個異步 HTTP 請求可以使用單一連接</li><li>報頭使用 HPACK 壓縮</li><li>服務器推送 - 單個請求多個響應</li><li>請求優先級</li><li>安全性</li></ul><p><img src="http://i.imgur.com/S85j8gg.png" alt=""></p><h4 id="_1-二進制協議" tabindex="-1">1. 二進制協議 <a class="header-anchor" href="#_1-二進制協議" aria-label="Permalink to “1. 二進制協議”">​</a></h4><p><code>HTTP/2</code> 通過使其成為一個二進制協議以解決 HTTP/1.x 中存在的延遲問題。作為一個二進制協議，它更容易解析，但可讀性卻不如 <code>HTTP/1.x</code>。幀（frames）和流（stream）的概念組成了 <code>HTTP/2</code> 的主要部分。</p><p><strong>幀和流</strong></p>',15)),d("p",null,[e[20]||(e[20]=s("現在 HTTP 消息是由一個或多個幀組成的。<code>HEADERS</code> 幀承載了元數據（meta data），<code>DATA</code> 幀則承載了內容。還有其他類型的幀（<code>HEADERS</code>、<code>DATA</code>、<code>RST_STREAM</code>、<code>SETTINGS</code>、<code>PRIORITY</code> 等等），這些你可以通過",15)),n(t,{href:"https://http2.github.io/http2-spec/#FrameTypes"},{default:l(()=>[...e[19]||(e[19]=[o("HTTP/2 規範",-1)])]),_:1}),e[21]||(e[21]=o("來了解。",-1))]),e[47]||(e[47]=s('<p>每個 <code>HTTP/2</code> 請求和響應都被賦予一個唯一的流 ID，並切分成幀。幀就是一小片二進制數據。幀的集合稱為流，每個幀都有個標識了其所屬流的流 ID，所以在同一個流下的每個幀具有共同的報頭。值得注意的是，​除了流 ID 是唯一的之外，​由客户端發起的請求使用了奇數作為流 ID，從來自服務器的響應使用了偶數作為流 ID。</p><p>除了 <code>HEADERS</code> 幀和 <code>DATA</code> 幀，另一個值得一提的幀是 <code>RST_STREAM</code>。這是一個特殊的幀類型，用來中止流，即客户可以發送此幀讓服務器知道，我不再需要這個流了。在 <code>HTTP/1.1</code> 中讓服務器停止給客户端發送響應的唯一方法是關閉連接，這樣造成了延遲增加，因為之後要發送請求時，就要必須打開一個新的請求。而在 <code>HTTP/2</code> ，客户端可以使用 <code>RST_STREAM</code> 來停止接收特定的數據流，而連接仍然打開着，可以被其他請求使用。</p><h4 id="_2-多路傳輸" tabindex="-1">2. 多路傳輸 <a class="header-anchor" href="#_2-多路傳輸" aria-label="Permalink to “2. 多路傳輸”">​</a></h4><p>因為 <code>HTTP/2</code> 是一個二進制協議，而且如上所述它使用幀和流來傳輸請求與響應，一旦建立了 TCP 連接，相同連接內的所有流都可以同過這個 TCP 連接異步發送，而不用另外打開連接。反過來説，服務器也可以使用同樣的異步方式返回響應，也就是説這些響應可以是無序的，客户端使用分配的流 ID 來識別數據包所屬的流。這也解決了 HTTP/1.x 中請求管道被阻塞的問題，即客户端不必等待佔用時間的請求而其他請求仍然可以被處理。</p><h4 id="_3-hpack-請求頭部壓縮" tabindex="-1">3. HPACK 請求頭部壓縮 <a class="header-anchor" href="#_3-hpack-請求頭部壓縮" aria-label="Permalink to “3. HPACK 請求頭部壓縮”">​</a></h4><p>RFC 花了一篇文檔的篇幅來介紹針對發送的頭信息的優化，它的本質是當我們在同一客户端上不斷地訪問服務器時，許多冗餘數據在頭部中被反覆發送，有時候僅僅是 cookies 就能增加頭信息的大小，這會佔用許多寬帶和增加傳輸延遲。為了解決這個問題，<code>HTTP/2</code> 引入了頭信息壓縮。</p><p><img src="http://i.imgur.com/3IPWXvR.png" alt=""></p><p>不像請求和響應那樣，頭信息中的信息不會以 <code>gzip</code> 或者 <code>compress</code> 等格式壓縮。而是採用一種不同的機制來壓縮頭信息，客户端和服務器同時維護一張頭信息表，儲存了使用了哈夫曼編碼進行編碼後的頭信息的值，並且後續請求中若出現同樣的字段則忽略重複值（例如用户代理（user agent）等），只發送存在兩邊信息表中它的引用即可。</p><p>我們説的頭信息，它們同 HTTP/1.1 中一樣，並在此基礎上增加了一些偽頭信息，如 <code>:scheme</code>，<code>:host</code> 和 <code>:path</code>。</p><h4 id="_4-服務器推送" tabindex="-1">4. 服務器推送 <a class="header-anchor" href="#_4-服務器推送" aria-label="Permalink to “4. 服務器推送”">​</a></h4><p>服務器推送是 <code>HTTP/2</code> 的另一個巨大的特點。對於服務器來説，當它知道客户端需要一定的資源後，它可以把數據推送到客户端，即使客户端沒有請求它。例如，假設一個瀏覽器在加載一個網頁時，它解析了整個頁面，發現有一些內容必須要從服務端獲取，然後發送相應的請求到服務器以獲取這些內容。</p><p>服務器推送減少了傳輸這些數據需要來回請求的次數。它是如何做到的呢？服務器通過發送一個名字為 <code>PUSH_PROMISE</code> 特殊的幀通知到客户端“嘿，我準備要發送這個資源給你了，不要再問我要了。”這個 <code>PUSH_PROMISE</code> 幀與要產生推送的流聯繫在一起，並包含了要推送的流 ID，也就是説這個流將會被服務器推送到客户端上。</p><h4 id="_5-請求優先級" tabindex="-1">5. 請求優先級 <a class="header-anchor" href="#_5-請求優先級" aria-label="Permalink to “5. 請求優先級”">​</a></h4><p>當流被打開的時候，客户端可以在 <code>HEADERS</code> 幀中包含優先級信息來為流指定優先級。在任何時候，客户端都可以發送 <code>PRIORITY</code> 幀來改變流的優先級。</p><p>如果沒有任何優先級信息，服務器將異步地無序地處理這些請求。如果流分配了優先級，服務器將基於這個優先級來決定需要分配多少資源來處理這個請求。</p><h4 id="_6-安全性" tabindex="-1">6. 安全性 <a class="header-anchor" href="#_6-安全性" aria-label="Permalink to “6. 安全性”">​</a></h4><p>在是否強制使用 <code>TLS</code> 來增加安全性的問題上產生了大範圍的討論，討論的結果是不強制使用。然而大多數廠商只有在使用 <code>TLS</code> 時才能使用 <code>HTTP/2</code>。所以 <code>HTTP/2</code> 雖然規範上不要求加密，但是加密已經約定俗成了。這樣，在 <code>TLS</code> 之上實現 <code>HTTP/2</code> 就有了一些強制要求，比如，<code>TLS</code> 的最低版本為 <code>1.2</code>，必須達到某種級別的最低限度的密鑰大小，需要佈署 ephemeral 密鑰等等。</p>',17)),d("p",null,[e[23]||(e[23]=o("到現在 ",-1)),e[24]||(e[24]=d("code",null,"HTTP/2",-1)),e[25]||(e[25]=o(" 已經",-1)),n(t,{href:"http://caniuse.com/#search=http2"},{default:l(()=>[...e[22]||(e[22]=[o("完全超越了 SPDY",-1)])]),_:1}),e[26]||(e[26]=o("，並且還在不斷成長，HTTP/2 有很多關係性能的提升，我們應該開始佈署它了。",-1))]),d("p",null,[e[29]||(e[29]=o("如果你想更深入的瞭解細節，請訪問",-1)),n(t,{href:"https://http2.github.io/http2-spec"},{default:l(()=>[...e[27]||(e[27]=[o("該規範的鏈接",-1)])]),_:1}),e[30]||(e[30]=o("和",-1)),n(t,{href:"http://www.http2demo.io/"},{default:l(()=>[...e[28]||(e[28]=[o(" HTTP/2 性能提升演示的鏈接",-1)])]),_:1}),e[31]||(e[31]=o("。請在留言板寫下你的疑問或者評論，最後如果你發現有錯誤，請同樣留言指出。",-1))]),e[48]||(e[48]=d("p",null,"這就是全部了，我們之後再見~",-1)),e[49]||(e[49]=d("hr",null,null,-1)),d("p",null,[e[33]||(e[33]=o("via: ",-1)),n(t,{href:"http://kamranahmed.info/blog/2016/08/13/http-in-depth/"},{default:l(()=>[...e[32]||(e[32]=[o("http://kamranahmed.info/blog/2016/08/13/http-in-depth/",-1)])]),_:1})]),d("p",null,[e[37]||(e[37]=o("作者：",-1)),n(t,{href:"http://github.com/kamranahmedse"},{default:l(()=>[...e[34]||(e[34]=[o("Kamran Ahmed",-1)])]),_:1}),e[38]||(e[38]=o(" 譯者：",-1)),n(t,{href:"https://github.com/NearTan"},{default:l(()=>[...e[35]||(e[35]=[o("NearTan",-1)])]),_:1}),e[39]||(e[39]=o(" 校對：",-1)),n(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[36]||(e[36]=[o("wxy",-1)])]),_:1})]),d("p",null,[e[42]||(e[42]=o("本文由 ",-1)),n(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[40]||(e[40]=[o("LCTT",-1)])]),_:1}),e[43]||(e[43]=o(" 原創編譯，",-1)),n(t,{href:"https://linux.cn/"},{default:l(()=>[...e[41]||(e[41]=[o("Linux中國",-1)])]),_:1}),e[44]||(e[44]=o(" 榮譽推出",-1))])])}const k=a(r,[["render",c]]);export{f as __pageData,k as default};
